from __future__ import annotations

from fractions import Fraction
from numbers import Number
from typing import Any


_ZERO = Fraction(0, 1)
_RELEASE_RATIO = Fraction(4, 5)


def _numeric(value: Any) -> Fraction:
    """Convert a legacy numeric value to an exact rational number."""
    if value is None:
        return _ZERO

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return _ZERO
        return Fraction(value)

    if isinstance(value, bool):
        return Fraction(int(value), 1)

    if isinstance(value, int):
        return Fraction(value, 1)

    # Converting through str avoids preserving binary floating-point artifacts.
    return Fraction(str(value))


def _primary_key_sort_key(value: Any) -> tuple[Any, ...]:
    """Provide deterministic ascending ordering for ordinary CRM key types."""
    if value is None:
        return (0, "")

    if isinstance(value, Number) and not isinstance(value, complex):
        return (1, _numeric(value))

    if isinstance(value, str):
        return (2, value)

    return (3, type(value).__name__, repr(value))


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[Any, Fraction] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        account_id = order.get("ACCT_ID")
        exposure_by_account[account_id] = (
            exposure_by_account.get(account_id, _ZERO)
            + _numeric(order.get("TOT_AMT"))
        )

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(
        key=lambda index: _primary_key_sort_key(
            new_accounts[index].get("ACCT_ID")
        )
    )

    for index in eligible_indices:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(account_id, _ZERO)
        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * _RELEASE_RATIO
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
